export type BuiltinExercise = {
  id: string;
  name: string;
  bodyPart: string;
  equipment: string;
  difficulty: string;
  description: string;
};

export const BUILTIN_EXERCISES: BuiltinExercise[] = [
  // CHEST
  { id: "bench-press", name: "Bench Press", bodyPart: "chest", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Chest, front of your shoulders, back of your upper arms\n📋 How to do it: 1. Lie flat on the bench with your eyes directly under the bar and feet flat on the floor. 2. Grip the bar just wider than shoulder-width, pinch your shoulder blades together, and unrack. 3. Lower the bar slowly to your lower chest, keeping your elbows at about 45°. 4. Press the bar back up in a smooth arc until your arms are straight.\n💡 Key tip: Keep your shoulder blades squeezed together throughout — this protects your shoulders and gives you a more stable base. Never bounce the bar off your chest." },
  { id: "incline-bench", name: "Incline Bench Press", bodyPart: "chest", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Upper chest, front of your shoulders, back of your upper arms\n📋 How to do it: 1. Set the bench to 30–45° — any higher shifts the load onto your shoulders rather than your upper chest. 2. Grip the bar slightly wider than shoulder-width and unrack. 3. Lower the bar slowly to your upper chest, just below your collarbone. 4. Press back up until arms are straight, keeping elbows at about 45° from your body.\n💡 Key tip: Keep the angle at 30° for maximum upper chest work. At 45° or higher, the front of your shoulders takes over and your chest does less." },
  { id: "decline-bench", name: "Decline Bench Press", bodyPart: "chest", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Lower chest, back of your upper arms, front of your shoulders\n📋 How to do it: 1. Set the bench to 15–30° decline and secure your feet under the pads. 2. Grip the bar slightly wider than shoulder-width. 3. Lower the bar slowly to your lower chest in a controlled movement. 4. Press back up to the starting position with arms fully extended.\n💡 Key tip: The bar path sits lower on your chest than flat bench. This version is often more comfortable for people who feel shoulder pain during flat pressing." },
  { id: "db-press", name: "DB Flat Press", bodyPart: "chest", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Chest, front of your shoulders, back of your upper arms\n📋 How to do it: 1. Lie flat on a bench with a dumbbell in each hand at chest height, palms facing forward. 2. Lower both dumbbells out and down until your elbows drop just below bench level. 3. Feel the stretch across your chest at the bottom, then press back up. 4. Bring the dumbbells slightly toward each other at the top without clanging them together.\n💡 Key tip: Each arm works independently — great for fixing any left-to-right strength imbalance. You get a bigger range of motion than with a barbell." },
  { id: "incline-db", name: "Incline DB Press", bodyPart: "chest", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Upper chest, front of your shoulders, back of your upper arms\n📋 How to do it: 1. Set the bench to 30–45° and sit back with a dumbbell in each hand resting on your thighs. 2. Use your thighs to kick the dumbbells up to shoulder height as you lie back. 3. Lower both dumbbells out and down in a controlled arc until you feel a stretch in your upper chest. 4. Press back up, bringing the dumbbells slightly together at the top.\n💡 Key tip: Control the way down — don't let the weights drop fast. The slower the descent, the more work your muscles do." },
  { id: "cable-fly", name: "Cable Fly", bodyPart: "chest", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Chest — especially the inner chest area\n📋 How to do it: 1. Set both cables to chest height and stand in the middle with one foot slightly forward. 2. Take one handle in each hand with a slight bend in your elbows. 3. Bring both hands forward in a wide hugging arc until they meet in front of your chest. 4. Slowly let them travel back out to the sides until you feel a full stretch, then repeat.\n💡 Key tip: Cables maintain tension on your chest through the entire movement — unlike dumbbells which lose it at the top. Think 'hugging a tree' on every rep." },
  { id: "pec-deck", name: "Pec Deck", bodyPart: "chest", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Chest — especially the inner chest area\n📋 How to do it: 1. Adjust the seat height so the handles are at chest level and sit firmly against the back pad. 2. Place your forearms on the pads or grip the handles with arms slightly bent. 3. Squeeze your chest to bring the pads together in front of you. 4. Slowly release back to the open position, feeling the stretch across your chest before each rep.\n💡 Key tip: Great for beginners learning to feel their chest working — no balance required. Best used as a warm-up or finisher to pump blood into the chest without taxing your joints." },
  { id: "dips-chest", name: "Dips (Chest)", bodyPart: "chest", equipment: "bodyweight", difficulty: "intermediate",
    description: "🎯 Targets: Lower chest, back of your upper arms, front of your shoulders\n📋 How to do it: 1. Grip the parallel bars and get to the top position with arms straight. 2. Lean your torso forward 30–45° — this is what shifts the load to your chest. 3. Lower yourself until you feel a stretch across your lower chest, letting your elbows flare slightly outward. 4. Push back up to the starting position without fully locking your elbows.\n💡 Key tip: The forward lean is what makes this a chest exercise. If you stay upright, it becomes mostly a tricep exercise. Add a weight belt once bodyweight is easy." },
  { id: "pushups", name: "Push-ups", bodyPart: "chest", equipment: "bodyweight", difficulty: "beginner",
    description: "🎯 Targets: Chest, front of your shoulders, back of your upper arms, core\n📋 How to do it: 1. Start in a high plank with hands slightly wider than shoulder-width and your body in a straight line from head to heels. 2. Brace your core tight — don't let your hips sag. 3. Lower your chest toward the floor, keeping your elbows at roughly 45° to your body. 4. Push the floor away to return to the top.\n💡 Key tip: Keep your core braced the whole time. To make it harder, elevate your feet on a bench (shifts more work to your upper chest), or wear a weighted vest." },
  { id: "svend-press", name: "Svend Press", bodyPart: "chest", equipment: "plate", difficulty: "beginner",
    description: "🎯 Targets: Inner chest\n📋 How to do it: 1. Hold a weight plate between your palms at chest height, pressing your hands hard into each other. 2. Maintain that inward squeezing pressure the entire time — this is the whole point of the exercise. 3. Press the plate forward away from your chest until your arms are nearly straight. 4. Bring it back to your chest slowly.\n💡 Key tip: The constant squeezing pressure is what trains the inner chest. The moment you ease off the squeeze, the exercise loses its purpose." },
  { id: "landmine-press", name: "Landmine Press", bodyPart: "chest", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Upper chest, front of your shoulders, back of your upper arms\n📋 How to do it: 1. Anchor a barbell in the corner of the room or a landmine attachment and stand facing the end. 2. Pick up the free end with one or both hands at chest height. 3. Press the barbell end forward and up in a natural arc until your arm is nearly straight. 4. Lower it back to your chest under control.\n💡 Key tip: Works well as a single-arm press for added core engagement. The natural arc of the movement hits the upper chest very effectively." },
  { id: "db-pullover", name: "DB Pullover", bodyPart: "chest", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Chest and the wide muscles down the sides of your back\n📋 How to do it: 1. Lie across a bench so your upper back is supported, hips dropped below bench level. 2. Hold one dumbbell overhead with both hands, arms slightly bent — never fully locked. 3. Lower the dumbbell in an arc behind your head until you feel a big stretch through your chest and sides. 4. Pull it back overhead to the starting position.\n💡 Key tip: Keep a slight bend in your elbows throughout to protect your joints. Keep elbows close to your head for more back involvement, a wider arc for more chest." },

  // BACK
  { id: "deadlift", name: "Deadlift", bodyPart: "back", equipment: "barbell", difficulty: "advanced",
    description: "🎯 Targets: The entire back of your body — lower back, glutes, back of your legs, and upper back\n📋 How to do it: 1. Stand with the bar over your mid-foot, feet hip-width apart. Hinge down and grip the bar just outside your legs. 2. Get your chest up and take a big breath to brace your core hard — like you're about to be punched. 3. Push the floor away with your legs rather than pulling the bar up. 4. Once the bar passes your knees, drive your hips forward and stand tall, squeezing your glutes at the top.\n💡 Key tip: Never let your lower back round. This is one of the most important exercises you can do for your entire body — but technique must come before weight. Start light and earn the load." },
  { id: "barbell-row", name: "Barbell Row", bodyPart: "back", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Upper and mid-back, rear of your shoulders, biceps\n📋 How to do it: 1. Stand over the bar and hinge forward at the hips until your torso is roughly 45°, back flat. 2. Grip the bar just outside shoulder-width with an overhand grip. 3. Pull the bar into your lower chest or upper stomach, driving your elbows back and up. 4. Squeeze your shoulder blades together at the top, then lower the bar under full control.\n💡 Key tip: Don't use your lower back to jerk the weight up — if you're rocking back and forth, the weight is too heavy. Control matters more than load here." },
  { id: "pullups", name: "Pull-ups", bodyPart: "back", equipment: "bodyweight", difficulty: "intermediate",
    description: "🎯 Targets: Back width, biceps, rear of your shoulders\n📋 How to do it: 1. Grip the bar overhand with hands slightly wider than shoulder-width. 2. Hang with arms fully straight and let your shoulder blades relax at the very bottom. 3. Pull yourself up by driving your elbows down toward your hips — not just pulling with your hands. 4. Get your chin over the bar, squeeze at the top, then lower all the way back down slowly.\n💡 Key tip: Think about pulling your elbows toward your back pockets — this activates your back far more effectively and reduces arm fatigue." },
  { id: "chinups", name: "Chin-ups", bodyPart: "back", equipment: "bodyweight", difficulty: "intermediate",
    description: "🎯 Targets: Back width, biceps\n📋 How to do it: 1. Grip the bar underhand with hands at shoulder-width apart. 2. Hang with arms fully straight. 3. Pull yourself up, driving your elbows down and back. 4. Get your chin over the bar, hold briefly at the top, then lower yourself slowly all the way back down.\n💡 Key tip: The underhand grip makes your biceps contribute more, making this slightly easier than pull-ups. Great for building both back width and arm size at the same time." },
  { id: "lat-pulldown", name: "Lat Pulldown", bodyPart: "back", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Back width, biceps\n📋 How to do it: 1. Grip the bar wider than shoulder-width and sit down, locking your thighs under the pads. 2. Lean back slightly and look up toward the bar. 3. Pull the bar down to your upper chest, driving your elbows down and back toward your hips. 4. Slowly return the bar all the way back up, letting your arms fully extend and your shoulder blades stretch apart at the top.\n💡 Key tip: Feel the full stretch through the wide muscles of your back at the top of every rep — this is where a lot of the growth stimulus comes from. This is essentially a machine pull-up." },
  { id: "seated-row", name: "Seated Cable Row", bodyPart: "back", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Mid-back thickness, rear of your shoulders, biceps\n📋 How to do it: 1. Sit upright with your feet on the platform and a slight bend in your knees. 2. Reach forward and grip the handle, keeping your back straight as you do. 3. Pull the handle into your lower stomach, keeping your elbows close to your sides. 4. Squeeze your shoulder blades together at the end of the row, then let the cable slowly pull your arms back to the starting stretch.\n💡 Key tip: Keep your torso upright and avoid rocking back and forth. This builds back thickness — it's a different function to the pulldown which builds width." },
  { id: "tbar-row", name: "T-Bar Row", bodyPart: "back", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Mid-back thickness, back width, rear of your shoulders\n📋 How to do it: 1. Straddle the T-bar and hinge forward until your torso is at roughly 45°, chest up. 2. Grip the handles and keep your back flat throughout. 3. Row the bar into your chest, driving your elbows back and up past your body. 4. Squeeze your shoulder blades hard at the top, then lower under full control.\n💡 Key tip: A narrow grip hits the middle of your back more; a wider grip brings more of the outer back into play. One of the best exercises available for building serious back thickness." },
  { id: "db-row", name: "Single Arm DB Row", bodyPart: "back", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Back, rear of your shoulders, biceps\n📋 How to do it: 1. Place one knee and the same-side hand on a bench, with your back flat and the other foot on the floor. 2. Let the dumbbell hang from a straight arm directly below your shoulder. 3. Row the dumbbell up toward your hip, driving your elbow back and up past your body. 4. Lower the dumbbell all the way back to a full stretch before each rep.\n💡 Key tip: Think 'elbow to the ceiling behind you' — not just 'elbow to your hip'. This cue gets your back working far more and reduces how much your arm takes over." },
  { id: "rack-pull", name: "Rack Pull", bodyPart: "back", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Upper back, the muscles between your neck and shoulders, glutes, back of your legs\n📋 How to do it: 1. Set the bar in a rack at just below knee height and set up exactly like a deadlift. 2. Grip the bar just outside your legs and brace your core hard. 3. Drive the floor away and pull the bar up your thighs. 4. Lock out fully at the top by squeezing your glutes and standing completely tall.\n💡 Key tip: A shortened deadlift that lets you handle significantly more weight. Focuses on upper back strength and the top portion of the pull where many people are weakest." },
  { id: "goodmorning", name: "Good Morning", bodyPart: "back", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Lower back, back of your legs, glutes\n📋 How to do it: 1. Set the bar on your upper back exactly like a squat, with a comfortable stance. 2. Keep a soft bend in your knees throughout — this is not a squat. 3. Push your hips back and hinge forward, letting your torso drop toward parallel while keeping your back completely flat. 4. Drive your hips forward to return to standing.\n💡 Key tip: Start with very light weight while learning this pattern. This movement places serious stress on your lower back if loaded before the technique is solid. Earn the weight slowly." },
  { id: "back-extension", name: "Back Extension", bodyPart: "back", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Lower back, glutes, back of your legs\n📋 How to do it: 1. Set up face-down on the hyperextension bench with your hips at the top edge of the pad and feet secured. 2. Cross your arms over your chest or hold a weight plate at your chest. 3. Lower your upper body toward the floor in a controlled arc. 4. Raise back up until your body is parallel to the floor — stop there.\n💡 Key tip: Don't go past parallel — it adds no benefit and stresses your spine. Squeeze your glutes at the top of each rep. Hold a weight plate at your chest to progressively increase the difficulty." },
  { id: "meadows-row", name: "Meadows Row", bodyPart: "back", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: The outer part of your back, biceps\n📋 How to do it: 1. Anchor a barbell in the corner or a landmine. Stand to the side of it with a slightly staggered stance. 2. Hinge forward and grip the end of the bar with the far hand, using a neutral grip (thumb side up). 3. Row the bar up toward your hip, driving your elbow back and up past your body. 4. Lower slowly under full control, letting your arm fully extend before each rep.\n💡 Key tip: The angled direction of pull gives a unique stretch through the lower-outer part of your back that regular rows don't replicate. Excellent for back thickness and detail." },

  // SHOULDERS
  { id: "ohp", name: "Overhead Press", bodyPart: "shoulders", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Front and side of your shoulders, back of your upper arms, muscles between your neck and shoulders\n📋 How to do it: 1. Set the bar at collarbone height in a rack, grip just outside shoulder-width. 2. Brace your core hard and squeeze your glutes — no excessive lower back arch. 3. Press the bar straight overhead, pushing your head forward through the gap as the bar clears your face. 4. Lock out fully overhead, then lower the bar back to your collarbone under control.\n💡 Key tip: Think tall spine throughout — don't lean back. One of the best measures of upper body pressing strength and a key builder for overall shoulder size." },
  { id: "db-ohp", name: "DB Shoulder Press", bodyPart: "shoulders", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Front and side of your shoulders, back of your upper arms\n📋 How to do it: 1. Sit on an upright bench or stand with a dumbbell in each hand at shoulder height, palms facing forward. 2. Brace your core if standing to avoid your lower back arching. 3. Press both dumbbells overhead until arms are nearly straight, bringing them slightly together at the top. 4. Lower back to shoulder height under full control.\n💡 Key tip: Greater range of motion than the barbell version. Seated takes your lower body completely out of the equation, letting you focus purely on the shoulders." },
  { id: "arnold-press", name: "Arnold Press", bodyPart: "shoulders", equipment: "dumbbell", difficulty: "intermediate",
    description: "🎯 Targets: All three parts of the shoulder — front, side, and rear\n📋 How to do it: 1. Start with dumbbells in front of your face, palms facing toward you — as if you just finished a bicep curl. 2. As you begin pressing up, gradually rotate your palms to face forward. 3. Continue pressing until your arms are straight overhead. 4. Reverse the rotation as you lower back down to the starting position.\n💡 Key tip: Named after Arnold Schwarzenegger. The rotating motion trains all three parts of the shoulder through a larger arc than a standard press — making it one of the most complete shoulder exercises you can do." },
  { id: "lateral-raises", name: "Lateral Raises", bodyPart: "shoulders", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Side of the shoulder — what gives your shoulders their width\n📋 How to do it: 1. Stand with a dumbbell in each hand by your sides, a slight bend in your elbows. 2. Raise both arms out to the sides simultaneously, leading with your elbows rather than your hands. 3. Bring them to shoulder height — you don't need to go higher. 4. Lower slowly under full control. Don't let the weights drop.\n💡 Key tip: The primary exercise for building shoulder width. Never swing your body or shrug your neck to get the weight up — strict form with lighter weight beats cheating with too much." },
  { id: "front-raises", name: "Front Raises", bodyPart: "shoulders", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Front of the shoulder\n📋 How to do it: 1. Stand holding dumbbells in front of your thighs, palms facing your legs. 2. Raise both arms straight forward until they reach shoulder height. 3. Hold for a brief moment at the top. 4. Lower slowly and under control back to your sides.\n💡 Key tip: Most pressing exercises already work the front of your shoulders heavily. If you bench press and overhead press regularly, this area rarely needs extra direct work — use it sparingly." },
  { id: "face-pulls", name: "Face Pulls", bodyPart: "shoulders", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Rear of the shoulder, upper back, small stabilising muscles in your shoulder joint\n📋 How to do it: 1. Attach a rope to a cable set at roughly face height and grip both ends with palms facing inward. 2. Step back until there's tension on the cable. 3. Pull the rope toward your face, driving your elbows back and high — your hands should end up beside your ears with elbows flared. 4. Hold that end position for one second, then slowly return.\n💡 Key tip: One of the most important exercises for shoulder health and posture. The rear of the shoulder is almost always underdeveloped. If you press a lot, do these every session." },
  { id: "upright-row", name: "Upright Row", bodyPart: "shoulders", equipment: "barbell", difficulty: "beginner",
    description: "🎯 Targets: Side of the shoulder, muscles between your neck and shoulders\n📋 How to do it: 1. Grip the bar with hands narrower than shoulder-width and hold it at your thighs. 2. Pull the bar straight up along the front of your body, flaring your elbows out to the sides. 3. Bring it to about chin height. 4. Lower slowly back to your thighs.\n💡 Key tip: This can cause shoulder pain for some people when the elbows go higher than the hands. If you feel any pinching or discomfort, switch to a cable or wider dumbbell variation." },
  { id: "cable-lateral", name: "Cable Lateral Raise", bodyPart: "shoulders", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Side of the shoulder\n📋 How to do it: 1. Stand side-on to a low cable pulley. 2. Cross your body and grip the handle with the hand farthest from the machine. 3. Raise your arm out to the side until it reaches shoulder height, keeping a slight bend in your elbow. 4. Lower slowly under control back to the start.\n💡 Key tip: The cable keeps tension on the side of your shoulder even at the very bottom of the movement, where a dumbbell goes completely slack. More consistent tension through the full range." },
  { id: "machine-press", name: "Machine Shoulder Press", bodyPart: "shoulders", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Front and side of your shoulders, back of your upper arms\n📋 How to do it: 1. Adjust the seat so the handles are at shoulder height and sit firmly against the back pad. 2. Grip both handles and press straight overhead until arms are nearly straight. 3. Hold briefly at the top. 4. Lower under full control back to shoulder height.\n💡 Key tip: The fixed movement path makes this safer and easier to learn than free weights. Excellent for high-rep shoulder work or when your stabiliser muscles are already fatigued from heavy pressing." },
  { id: "shrugs", name: "Barbell Shrugs", bodyPart: "shoulders", equipment: "barbell", difficulty: "beginner",
    description: "🎯 Targets: The muscles between your neck and your shoulders\n📋 How to do it: 1. Hold the barbell in front of your thighs with a firm double overhand grip, arms straight. 2. Keep your arms straight throughout — they should not bend. 3. Shrug your shoulders straight up toward your ears as high as possible. 4. Hold at the top for one second, then lower slowly.\n💡 Key tip: Move straight up and down only — do not roll your shoulders forward or backward in circles. Rolling adds nothing and puts your shoulder joints under unnecessary stress." },

  // ARMS
  { id: "bb-curl", name: "Barbell Curl", bodyPart: "arms", equipment: "barbell", difficulty: "beginner",
    description: "🎯 Targets: Biceps, front of the upper arm\n📋 How to do it: 1. Stand holding the barbell with an underhand grip at about hip width. 2. Pin your elbows firmly to your sides — keep them there for the whole set. 3. Curl the bar from your thighs up to your upper chest in a smooth controlled arc. 4. Lower back down slowly under full control — don't just drop it.\n💡 Key tip: The foundational bicep mass builder. Use an EZ-bar if the straight bar causes wrist discomfort — it puts your hands in a more natural angle." },
  { id: "db-curl", name: "DB Curl", bodyPart: "arms", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Biceps\n📋 How to do it: 1. Stand or sit with a dumbbell in each hand by your sides, palms facing forward. 2. Keep your elbows fixed to your sides throughout. 3. Curl the dumbbells up toward your shoulders, one or both at a time. 4. At the top, rotate your pinky finger slightly outward for a stronger contraction, then lower slowly.\n💡 Key tip: Don't let your elbows swing forward as you curl — if they move, you're using momentum rather than your biceps. Go lighter and keep it strict." },
  { id: "hammer-curl", name: "Hammer Curl", bodyPart: "arms", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Overall upper arm thickness — biceps and the muscle underneath\n📋 How to do it: 1. Stand holding dumbbells with a neutral grip (palms facing each other) from start to finish. 2. Pin your elbows to your sides. 3. Curl the dumbbells up toward your shoulders, keeping the palms-facing grip the whole time. 4. Lower slowly back to the start.\n💡 Key tip: The neutral grip targets the deeper muscles of the upper arm — giving the arm a thick, full look from the side. One of the best exercises for overall arm size." },
  { id: "preacher-curl", name: "Preacher Curl", bodyPart: "arms", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Biceps — especially the peak\n📋 How to do it: 1. Sit at the preacher bench and rest your upper arms on the pad with your armpits over the top edge. 2. Grip the bar with an underhand grip. 3. Curl the weight up toward your face in a controlled arc. 4. Lower slowly until your arms are fully extended — take the full stretch at the bottom before each rep.\n💡 Key tip: The pad locks your elbows in place, eliminating any cheating. The full stretch at the bottom is where a lot of the stimulus comes from — don't skip it or let the weight crash down." },
  { id: "cable-curl", name: "Cable Curl", bodyPart: "arms", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Biceps\n📋 How to do it: 1. Attach a bar or rope to the low cable and stand facing the machine. 2. Grip the attachment with an underhand grip, elbows at your sides. 3. Curl up toward your face, keeping your upper arms completely still. 4. Lower slowly back to the start — feel the cable pulling against you all the way to the bottom.\n💡 Key tip: The cable maintains tension at the bottom of the movement where a dumbbell goes slack. Makes it excellent for high-rep finisher sets." },
  { id: "incline-db-curl", name: "Incline DB Curl", bodyPart: "arms", equipment: "dumbbell", difficulty: "intermediate",
    description: "🎯 Targets: Biceps — with a strong emphasis on the lower portion for a fuller look\n📋 How to do it: 1. Set a bench to 45–60° and lie back on it with a dumbbell in each hand. 2. Let your arms hang straight down behind your body — this stretched position is the whole key. 3. Curl both dumbbells up toward your shoulders in a controlled movement. 4. Lower fully back to the hanging stretched position before each rep.\n💡 Key tip: The inclined position stretches the bicep more than any standing curl can. This extra stretch is what makes this exercise so effective for building the lower part of the bicep for a fuller look." },
  { id: "skull-crushers", name: "Skull Crushers", bodyPart: "arms", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Back of the upper arm — triceps\n📋 How to do it: 1. Lie flat on a bench and hold an EZ-bar directly above your face with arms fully straight. 2. Keep your upper arms pointing straight up and completely still throughout. 3. Bend only at the elbows and lower the bar toward your forehead or just behind your head. 4. Extend back up to the starting position.\n💡 Key tip: Lowering behind your head gives a better stretch on the largest part of the tricep — this matters for overall arm size. Keep your upper arms locked vertical the whole time." },
  { id: "tricep-pushdown", name: "Tricep Pushdown", bodyPart: "arms", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Back of the upper arm — triceps\n📋 How to do it: 1. Attach a bar or rope to a high cable and stand close to the machine, elbows bent at 90° and upper arms pinned to your sides. 2. Push down until your arms are fully straight. 3. Squeeze the back of your upper arms hard at the bottom for one second. 4. Let the weight slowly raise your hands back to the 90° starting position.\n💡 Key tip: With a rope, flare your hands apart at the bottom for a stronger contraction. Your upper arms must stay locked at your sides — if they're moving, the weight is too heavy." },
  { id: "overhead-tri", name: "Overhead Tricep Extension", bodyPart: "arms", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Back of the upper arm — especially the largest inner portion\n📋 How to do it: 1. Face away from a cable with a rope attachment, or hold a dumbbell behind your head with both hands. 2. Position your elbows pointing at the ceiling with your upper arms against the sides of your head. 3. Keep your upper arms completely still as you extend your hands straight up overhead. 4. Lower back behind your head slowly and under control.\n💡 Key tip: One of the most important tricep exercises because it fully stretches the largest part of the muscle — which only happens when the arm is raised overhead. Most people only do pushdowns and miss this stretch entirely." },
  { id: "close-grip", name: "Close Grip Bench", bodyPart: "arms", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Back of the upper arm, chest, front of your shoulders\n📋 How to do it: 1. Lie flat on a bench and grip the bar at roughly shoulder-width or just inside it. 2. Unrack and hold the bar over your lower chest. 3. Lower the bar to your lower chest, keeping your elbows tucked in at roughly 45° to your body. 4. Press back up until arms are straight.\n💡 Key tip: The best compound exercise for loading the triceps with heavy weight. Don't grip too narrow — it stresses your wrists without adding any benefit. Shoulder-width is the sweet spot." },
  { id: "dips-tri", name: "Tricep Dips", bodyPart: "arms", equipment: "bodyweight", difficulty: "intermediate",
    description: "🎯 Targets: Back of the upper arm, front of your shoulders, chest\n📋 How to do it: 1. Grip the parallel bars and start at the top with arms straight and your torso upright. 2. Keep your torso upright throughout — leaning forward shifts the work to your chest. 3. Lower yourself by bending your elbows, keeping them tucked close to your sides. 4. Lower until elbows reach roughly 90°, then press back up.\n💡 Key tip: Staying upright keeps the focus on your triceps. Use a dip belt to add weight once bodyweight reps become easy." },
  { id: "kickbacks", name: "Tricep Kickbacks", bodyPart: "arms", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Back of the upper arm when fully extended\n📋 How to do it: 1. Hinge forward with one hand on a bench and your back flat, holding a dumbbell in the other hand. 2. Raise your upper arm until it's parallel to the floor, elbow bent at 90°. 3. Extend your forearm back until your arm is completely straight. 4. Squeeze hard at the fully extended position for one second, then lower slowly.\n💡 Key tip: This exercise only loads the tricep in the fully contracted position — so the squeeze at the top is everything. If your arm can't fully straighten, the weight is too heavy." },

  // LEGS
  { id: "squat", name: "Squat", bodyPart: "legs", equipment: "barbell", difficulty: "advanced",
    description: "🎯 Targets: Front of your legs, glutes, back of your legs, lower back, core\n📋 How to do it: 1. Place the bar across your upper back, feet shoulder-width apart with toes turned slightly outward. 2. Take a big breath, brace your core hard, and push your knees out over your toes as you begin to lower. 3. Sit down until your thighs are at least parallel to the floor — deeper if you have the mobility. 4. Drive back up through your whole foot, keeping your chest up and knees pushed out.\n💡 Key tip: Never let your lower back round. One of the most important lifts you can do for overall strength. If depth is limited, work on ankle and hip flexibility." },
  { id: "front-squat", name: "Front Squat", bodyPart: "legs", equipment: "barbell", difficulty: "advanced",
    description: "🎯 Targets: Front of your legs very heavily, glutes, upper back, core\n📋 How to do it: 1. Rest the bar on your front shoulders in the front rack position, keeping your elbows as high as possible. 2. Stand with feet shoulder-width, toes slightly out. 3. Brace your core and sit straight down, keeping your torso as upright as possible. 4. Drive back up through your whole foot, keeping elbows high to stop the bar rolling forward.\n💡 Key tip: Requires good ankle flexibility and the ability to hold a front rack. The upright torso takes pressure off your lower back and puts far more demand on the front of your legs than a back squat." },
  { id: "hack-squat", name: "Hack Squat", bodyPart: "legs", equipment: "machine", difficulty: "intermediate",
    description: "🎯 Targets: Front of your legs, glutes, back of your legs\n📋 How to do it: 1. Step into the machine and rest your shoulders and back against the pad, feet shoulder-width on the platform. 2. Release the safety handles and lower the sled in a slow, controlled descent. 3. Lower until your thighs reach parallel or slightly below. 4. Drive back up through your whole foot without fully locking your knees at the top.\n💡 Key tip: Foot placement changes the emphasis — higher and wider hits more glutes; lower and narrower puts more work on the front of your legs. Much less lower back stress than barbell squats." },
  { id: "leg-press", name: "Leg Press", bodyPart: "legs", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Front of your legs, glutes, back of your legs\n📋 How to do it: 1. Sit in the machine with your back flat against the pad and feet hip-width on the platform. 2. Disengage the safety handles and lower the sled in a controlled movement until knees reach 90°. 3. Press the platform back up through your whole foot. 4. Stop just short of locking your knees out at the top.\n💡 Key tip: Don't let your lower back round off the pad at the bottom — that's a sign you've gone too deep. High and wide feet hit more glutes; low and narrow feet hit more of the front of your legs." },
  { id: "rdl", name: "Romanian Deadlift", bodyPart: "legs", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Back of your legs, glutes, lower back\n📋 How to do it: 1. Stand holding the bar at hip height with feet hip-width apart. 2. Push your hips back and let the bar slide down the front of your thighs as your torso tips forward. 3. Lower until you feel a deep stretch in the back of your legs — typically just past your knees. 4. Drive your hips forward to return to standing, squeezing your glutes hard at the top.\n💡 Key tip: This is not a squat — your knees should barely bend. The stretch in the back of your legs at the bottom is what makes this effective. Keep your back completely flat the entire way down." },
  { id: "leg-curl", name: "Leg Curl", bodyPart: "legs", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Back of your legs\n📋 How to do it: 1. Set up in the machine — lying face-down with the pad just above your heels, or seated with the pad behind your lower legs. 2. Curl the pad toward your glutes (lying) or downward (seated) through the full range of motion. 3. Squeeze hard at the fully contracted position for one second. 4. Lower slowly back to the start, allowing a full stretch in the back of your legs.\n💡 Key tip: Lying trains the back of your legs with your hip extended. Seated trains them with your hip bent for more stretch. Using both variations gives more complete development over time." },
  { id: "leg-ext", name: "Leg Extension", bodyPart: "legs", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Front of your legs in isolation\n📋 How to do it: 1. Sit upright in the machine with the pad just above your ankle and your back flat against the seat. 2. Grip the side handles for stability. 3. Extend your legs until completely straight, squeezing the front of your legs hard at the top. 4. Lower slowly under full control — don't let the weight crash down.\n💡 Key tip: Don't go excessively heavy — the knee joint is in a vulnerable position at full extension. Best used as a warm-up to get blood into your knees, or as a finisher at the end of a leg session." },
  { id: "lunges", name: "Walking Lunges", bodyPart: "legs", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Front of your legs, glutes, back of your legs, and your balance\n📋 How to do it: 1. Stand upright with dumbbells by your sides (or bodyweight to start). 2. Step one foot forward and lower your rear knee toward the floor in a controlled drop. 3. Make sure your front knee stays over your toes — don't let it cave inward. 4. Push through your front heel to drive yourself forward into the next step.\n💡 Key tip: Keep your torso upright throughout — don't lean forward. You can load these with a barbell on your back, dumbbells, or a single weight held at your chest for variety." },
  { id: "bss", name: "Bulgarian Split Squat", bodyPart: "legs", equipment: "dumbbell", difficulty: "intermediate",
    description: "🎯 Targets: Front of your legs, glutes, the muscles at the top of your rear leg near your hip\n📋 How to do it: 1. Stand about 2–3 feet in front of a bench and place your rear foot up on it. 2. Position your front foot far enough forward that your knee stays roughly above your ankle when you lower down. 3. Lower your rear knee toward the floor in a controlled movement, keeping your torso upright. 4. Drive back up through your front heel.\n💡 Key tip: Start very light — this is much harder than it looks. The muscles at the top of your rear leg near your hip will be deeply stretched and will likely be sore the next day. That's completely normal." },
  { id: "calf-raises", name: "Calf Raises", bodyPart: "legs", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Outer calf muscle\n📋 How to do it: 1. Stand on the edge of a step or platform with your heels hanging off. 2. Lower your heels as far below the step as possible to get a full stretch. 3. Rise onto the balls of your feet as high as you can go. 4. Hold at the top for one second, then lower slowly back to the full stretch.\n💡 Key tip: Calves need high reps (15–25), sufficient weight, and a full range of motion. The stretch at the very bottom is critical — partial reps barely grow calves. They're stubborn and need serious effort." },
  { id: "seated-calf", name: "Seated Calf Raises", bodyPart: "legs", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: The deeper calf muscle that adds width to the lower leg\n📋 How to do it: 1. Sit on the machine with the pads resting on your lower thighs, just above your knees. 2. Let your heels drop as low as possible to get a full stretch at the bottom. 3. Rise onto the balls of your feet as high as you can go. 4. Hold briefly at the top, then lower slowly back to the full stretch.\n💡 Key tip: This deeper calf muscle is only targeted when your knee is bent — which is why this seated version exists. For complete calf development, you need both standing and seated calf work." },
  { id: "step-ups", name: "Step-ups", bodyPart: "legs", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Front of your legs and glutes on the working leg\n📋 How to do it: 1. Stand in front of a bench or box holding dumbbells by your sides. 2. Place one foot fully on the box, ensuring your whole foot is on the surface. 3. Drive through your heel and push up to stand on top of the box — don't push off the trailing foot on the floor. 4. Step back down and repeat on the same leg, or alternate each rep.\n💡 Key tip: All the work must come from the foot on the box — pushing off the back foot defeats the purpose. Higher box height = more glutes; lower box = more front of legs." },
  { id: "sumo-dl", name: "Sumo Deadlift", bodyPart: "legs", equipment: "barbell", difficulty: "intermediate",
    description: "🎯 Targets: Inner thighs, glutes, back of your legs, lower back\n📋 How to do it: 1. Take a wide stance with toes turned out and grip the bar just inside your legs. 2. Get your chest up and brace your core — your torso will be more upright than a regular deadlift. 3. Drive your feet into the floor and push your knees out hard over your toes. 4. Drive your hips forward to lock out at the top, squeezing your glutes.\n💡 Key tip: Shorter range of motion than the regular deadlift. People with wider hips often find this more natural. A good option for those who struggle with lower back comfort in the conventional stance." },
  { id: "goblet-squat", name: "Goblet Squat", bodyPart: "legs", equipment: "dumbbell", difficulty: "beginner",
    description: "🎯 Targets: Front of your legs, glutes, core\n📋 How to do it: 1. Hold a single dumbbell vertically at your chest with both hands cupping the top end. 2. Stand with feet shoulder-width apart, toes slightly turned out. 3. Squat down, letting your elbows drop inside your knees at the bottom — use your elbows to push your knees out. 4. Drive back up through your whole foot, keeping your chest tall.\n💡 Key tip: The weight held in front acts as a counterbalance, helping you stay upright. Perfect for learning proper squat mechanics or as a warm-up before heavier lifting." },

  // CORE
  { id: "plank", name: "Plank", bodyPart: "core", equipment: "bodyweight", difficulty: "beginner",
    description: "🎯 Targets: Deep core, shoulders, glutes\n📋 How to do it: 1. Place your forearms on the floor, elbows directly under your shoulders. 2. Step your feet back so your body forms a straight line from head to heels. 3. Squeeze your abs like you're about to be punched and clench your glutes firmly. 4. Hold this position without letting your hips sag down or your backside pike up.\n💡 Key tip: A 20-second plank with perfect tension is far more valuable than a 2-minute plank with a sagging back. Quality over duration every time." },
  { id: "cable-crunch", name: "Cable Crunch", bodyPart: "core", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Abs — the six-pack muscles\n📋 How to do it: 1. Kneel in front of a high cable and attach the rope, gripping each end beside your head. 2. Keep your hips completely still throughout — this is what makes it an ab exercise rather than a hip exercise. 3. Curl your elbows toward your knees, actively rounding your spine. 4. Hold the contracted position for one second, then slowly uncoil back to the top.\n💡 Key tip: Use your abs to flex your spine — don't just pull with your arms or rock your hips. One of the only core exercises where you can add weight progressively over time." },
  { id: "hanging-lr", name: "Hanging Leg Raise", bodyPart: "core", equipment: "bodyweight", difficulty: "intermediate",
    description: "🎯 Targets: Lower abs and the muscles at the top of your legs near your hips\n📋 How to do it: 1. Hang from a pull-up bar with arms straight and your body still. 2. Brace your core to prevent your body from swinging. 3. Raise your legs — bent knees is easier, straight legs is harder — until they're at least parallel to the floor. 4. Lower them slowly under full control.\n💡 Key tip: No swinging, no momentum — the slower the better. Start with bent knees and progress to straight legs as you get stronger. One of the best lower ab exercises available." },
  { id: "dead-bug", name: "Dead Bug", bodyPart: "core", equipment: "bodyweight", difficulty: "beginner",
    description: "🎯 Targets: Deep core stabilisers, lower back health\n📋 How to do it: 1. Lie flat on your back, arms pointing straight to the ceiling, knees bent at 90° in the air. 2. Press your lower back firmly into the floor — keep it pressed down for the entire exercise. 3. Slowly lower your right arm behind your head and your left leg toward the floor at the same time. 4. Return both to the start, then repeat with your left arm and right leg.\n💡 Key tip: If your lower back lifts off the floor at any point, stop and reset. This is as much a rehabilitation and injury prevention exercise as it is a strength exercise." },
  { id: "ab-wheel", name: "Ab Wheel", bodyPart: "core", equipment: "other", difficulty: "intermediate",
    description: "🎯 Targets: The entire core — especially the ability to stop your lower back from arching under load\n📋 How to do it: 1. Kneel on the floor holding the wheel with both hands, arms straight. 2. Brace your core firmly before moving. 3. Slowly roll the wheel forward as your body extends toward the floor, going as far as you can while keeping your lower back from arching. 4. Pull the wheel back using your core to return to the start.\n💡 Key tip: Start with partial rolls until you have the strength for the full movement. This is one of the hardest core exercises — if your lower back arches at the bottom, you've gone too far." },
  { id: "russian-twist", name: "Russian Twist", bodyPart: "core", equipment: "plate", difficulty: "beginner",
    description: "🎯 Targets: Side abs\n📋 How to do it: 1. Sit with knees bent and feet either on the floor or elevated for more difficulty. 2. Lean your torso back to about 45° so you're balanced on your tailbone. 3. Hold a plate or dumbbell with both hands and rotate your whole torso to the right, touching the weight to the floor. 4. Rotate back to the left — the movement comes from your torso, not just your arms.\n💡 Key tip: Rotate your whole torso to each side — don't just swing your arms. For more challenge, raise your feet and use a heavier plate." },
  { id: "pallof-press", name: "Pallof Press", bodyPart: "core", equipment: "cable", difficulty: "beginner",
    description: "🎯 Targets: Anti-rotation core strength, side abs\n📋 How to do it: 1. Stand side-on to a cable machine with the pulley at chest height. 2. Hold the handle at your chest with both hands clasped together. 3. Press the handle straight out in front of you and hold — resist the cable's pull to rotate you sideways. 4. Return the handle to your chest slowly. Complete all reps on one side, then turn around and repeat.\n💡 Key tip: Your core is working hard just to stop you rotating — this is how your core actually works in real life and sport. One of the most practical core exercises you can do." },
  { id: "dragon-flag", name: "Dragon Flag", bodyPart: "core", equipment: "bodyweight", difficulty: "advanced",
    description: "🎯 Targets: The entire core — especially the lower abs\n📋 How to do it: 1. Lie on a bench and grip it firmly behind your head with both hands. 2. Raise your entire body off the bench, keeping it completely rigid like a plank, pivoting at your shoulders. 3. Lower your body slowly toward horizontal — your whole body moves as one straight piece. 4. Raise back up before your body touches the bench, maintaining that rigid line.\n💡 Key tip: Master the lowering phase before attempting full reps. One of the most demanding bodyweight core exercises in existence, made famous by Bruce Lee." },
  { id: "side-plank", name: "Side Plank", bodyPart: "core", equipment: "bodyweight", difficulty: "beginner",
    description: "🎯 Targets: Side abs, hip stability\n📋 How to do it: 1. Lie on your side propped up on one forearm, elbow directly under your shoulder. 2. Stack your feet on top of each other (or stagger them for more stability). 3. Lift your hips off the floor so your body forms a straight diagonal line from head to feet. 4. Hold this position without letting your hips drop or your body rotate forward.\n💡 Key tip: Don't let your hips rotate toward the floor — keep your whole body in a tight straight line. To progress, add hip dips (tap the hip to the floor and lift back up) or raise your top leg." },
  { id: "v-ups", name: "V-Ups", bodyPart: "core", equipment: "bodyweight", difficulty: "beginner",
    description: "🎯 Targets: Upper and lower abs working together\n📋 How to do it: 1. Lie flat on the floor with arms extended straight behind your head and legs straight. 2. In one controlled movement, raise both your straight legs and your upper body simultaneously off the floor. 3. Reach your hands toward your feet at the top — your body forms a V shape. 4. Lower everything back down slowly under full control.\n💡 Key tip: The slow lowering phase is where most of the work happens — don't just drop back to the floor. Control every inch of the descent for maximum tension on the abs." },

  // CARDIO
  { id: "treadmill", name: "Treadmill", bodyPart: "cardio", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Heart and lungs, front of your legs, glutes, calves\n📋 How to do it: 1. Set your speed and incline and step onto the belt. 2. Maintain an upright posture — don't grip or lean on the handrails. 3. For steady-state cardio, work at a pace where you could hold a conversation (moderate effort). 4. For fat loss alongside lifting, aim for 20–40 minutes at this pace.\n💡 Key tip: Incline walking at 10–15° burns a significant amount of calories with almost no joint impact. A great alternative to running — if jogging causes knee pain, incline walking is the smarter option." },
  { id: "assault-bike", name: "Assault Bike", bodyPart: "cardio", equipment: "machine", difficulty: "intermediate",
    description: "🎯 Targets: Heart and lungs — full body effort\n📋 How to do it: 1. Sit on the bike and grip both handles, feet strapped to the pedals. 2. Begin pedalling and simultaneously pushing and pulling the handles — arms and legs work together. 3. The resistance self-regulates — the harder and faster you go, the more it pushes back. 4. Use intervals: 10 seconds of absolute maximum effort, then 50 seconds rest, repeated 8–10 times.\n💡 Key tip: Far harder than it looks — most people badly underestimate it the first time. Resistance drops the moment you ease off. A 10-second all-out sprint feels easy until about round five." },
  { id: "rowing", name: "Rowing Machine", bodyPart: "cardio", equipment: "machine", difficulty: "beginner",
    description: "🎯 Targets: Heart and lungs — legs, back, and arms all working together\n📋 How to do it: 1. Sit down, strap your feet in, and grip the handle. 2. Begin the drive by pushing with your legs first — this is 60% of the stroke. 3. Once your legs are nearly straight, lean back slightly — this is the next 20%. 4. Finally, pull the handle to your lower chest — the last 20%. Recovery reverses this exactly: arms out first, then lean forward, then bend knees.\n💡 Key tip: Most beginners pull with their arms first — this is wrong. Your legs do the heavy lifting. Damper setting 4–6 suits most people. Low-impact on the joints — good if running bothers your knees." },
  { id: "stairmaster", name: "StairMaster", bodyPart: "cardio", equipment: "machine", difficulty: "intermediate",
    description: "🎯 Targets: Heart and lungs, glutes, front of your legs\n📋 How to do it: 1. Step onto the machine and set a moderate pace before the stairs speed up on you. 2. Stand tall and upright — don't lean on the handrails or hunch forward. 3. Step deliberately on each stair, pushing through your whole foot. 4. Maintain a steady consistent pace for your target duration.\n💡 Key tip: Leaning heavily on the rails reduces the effort significantly. Higher glute and leg activation than flat treadmill walking — great for building the lower body while getting your cardio done." },
  { id: "jump-rope", name: "Jump Rope", bodyPart: "cardio", equipment: "other", difficulty: "beginner",
    description: "🎯 Targets: Heart and lungs, calves, coordination\n📋 How to do it: 1. Hold the handles lightly and position the rope behind your feet. 2. Swing the rope with your wrists — small tight circles, not big arm movements. 3. Jump just high enough to clear the rope, landing softly on the balls of your feet. 4. Build consistency at a steady pace before trying single-leg skipping or double-unders.\n💡 Key tip: Ten minutes of continuous skipping is roughly equivalent to a moderate jog. One of the most efficient and cheapest cardio tools available. Can be done anywhere." },
  { id: "sled-push", name: "Sled Push", bodyPart: "cardio", equipment: "other", difficulty: "advanced",
    description: "🎯 Targets: Front of your legs, glutes, and heart rate\n📋 How to do it: 1. Load the sled and grip the upright handles at about hip height. 2. Lean forward into the sled at roughly 45°. 3. Drive with short, rapid, powerful steps — keep your legs working the whole time. 4. Push for the set distance, rest, then repeat.\n💡 Key tip: Almost no muscle soreness the day after — very little eccentric loading. This makes it surprisingly good for conditioning on recovery days. Heavy loads build leg power; lighter loads at speed build cardio fitness." },
  { id: "farmers-carry", name: "Farmer's Carry", bodyPart: "cardio", equipment: "dumbbell", difficulty: "intermediate",
    description: "🎯 Targets: Grip strength, muscles between your neck and shoulders, core stability, and heart rate\n📋 How to do it: 1. Pick up heavy dumbbells or kettlebells with a firm grip, one in each hand. 2. Stand tall — pull your shoulders back and down, chest up. 3. Walk forward at a deliberate pace without letting your torso tilt sideways. 4. Set them down carefully after the set distance or time.\n💡 Key tip: One of the most practical exercises in existence — it translates directly to real-world strength. Load as heavy as you can while keeping a perfectly upright posture. If you're waddling side to side, go slightly lighter." },
  { id: "battle-ropes", name: "Battle Ropes", bodyPart: "cardio", equipment: "other", difficulty: "intermediate",
    description: "🎯 Targets: Shoulders, arms, and heart rate\n📋 How to do it: 1. Anchor the ropes at a fixed point and stand facing it with a rope end in each hand. 2. Take a slight squat stance to create a stable base. 3. Create alternating waves by rapidly driving one arm up as the other goes down, as fast as possible. 4. Go at maximum effort for your work interval (20–30 seconds), then rest completely before the next round.\n💡 Key tip: 20–30 second bursts at full effort with rest periods is the most effective way to use battle ropes. Trains shoulder endurance hard and is a staple of conditioning circuits." },
];
